// AUTOFILL LOGIC based on S.No
document.addEventListener('DOMContentLoaded', () => {
  const snoInput = document.getElementById('stateSno');
  if (snoInput) {
    snoInput.addEventListener('input', (e) => {
      const sno = parseInt(e.target.value);
      if (sno && snoToCatRanks2026[sno]) {
        const data = snoToCatRanks2026[sno];
        
        const airInput = document.getElementById('neetAIR');
        const scoreInput = document.getElementById('neetScore');
        const catSelect = document.getElementById('category');
        const genderSelect = document.getElementById('gender');
        
        if (airInput) { airInput.value = data.air; airInput.style.borderColor = '#10b981'; }
        if (scoreInput) { scoreInput.value = data.score; scoreInput.style.borderColor = '#10b981'; }
        
        if (catSelect) {
          // data.cat is like "OC", "BCA", "SC2"
          let mappedCat = data.cat;
          if (mappedCat.length === 3 && (mappedCat.startsWith('BC') || mappedCat.startsWith('SC'))) {
             mappedCat = mappedCat.substring(0,2) + '_' + mappedCat.substring(2);
          }
          if (data.ews && mappedCat === 'OC') {
             mappedCat = 'EWS';
          }
          catSelect.value = mappedCat;
          catSelect.style.borderColor = '#10b981';
        }
        
        if (genderSelect) {
          genderSelect.value = data.gender;
          genderSelect.style.borderColor = '#10b981';
        }
      }
    });
  }
});


// 1-Click Quick Predict Logic
// 1-Click Quick Predict & Auto Counselling Logic (Fixed for 2026)
function quickPredict() {
  const snoInput = document.getElementById('stateSno');
  const airInput = document.getElementById('neetAIR');
  const scoreInput = document.getElementById('neetScore');
  const catSelect = document.getElementById('categorySelect');
  const genderSelect = document.getElementById('genderSelect');
  const nameInput = document.getElementById('studentName');

  let sno = parseInt(snoInput?.value);
  let air = parseInt(airInput?.value);
  let score = parseInt(scoreInput?.value);

  // Auto-fill from Final Merit List if S.No or AIR provided
  if (!isNaN(sno) && snoToCatRanks2026[sno]) {
    const data = snoToCatRanks2026[sno];
    if (airInput && !airInput.value) airInput.value = data.air;
    if (scoreInput && !scoreInput.value) scoreInput.value = data.score;
    if (nameInput && !nameInput.value) nameInput.value = data.name;
    if (catSelect) {
      catSelect.value = data.cat;
      catSelect.style.borderColor = '#10b981';
    }
    if (genderSelect) {
      genderSelect.value = data.gender;
      genderSelect.style.borderColor = '#10b981';
    }
    air = data.air;
    score = data.score;
  } else if (!isNaN(air) && isNaN(sno)) {
    sno = estimateStateRank(air);
    if (snoInput) snoInput.value = sno;
    score = !isNaN(score) ? score : estimateScoreFromAIR(air);
    if (scoreInput) scoreInput.value = score;
  } else if (!isNaN(score) && isNaN(air)) {
    air = estimateRank(score);
    sno = estimateStateRank(air);
    if (airInput) airInput.value = air;
    if (snoInput) snoInput.value = sno;
  }

  if (isNaN(score) && isNaN(air) && isNaN(sno)) {
    showToast('Please enter your NEET Score, AIR, or State S.No', 'error');
    return;
  }

  const category = catSelect?.value || 'SC_2';
  const gender = genderSelect?.value || 'female';
  const name = nameInput?.value?.trim() || 'Student';

  studentProfile = {
    name,
    score: score || 393,
    category,
    gender,
    localStatus: 'local',
    pwd: document.getElementById('pwdCheckbox')?.checked || false,
    customAIR: air || 289635,
    customStateRank: sno || 8367
  };
  estimatedAIR = studentProfile.customAIR;

  // Build default Government First -> Private Next preferences
  preferences = buildPreferences('categorized');

  // Render Rank results for Step 2
  renderRankResults();

  // Execute Allocation Result directly for Step 4
  showAllocationResult();
}
